//! Runs the transcendental batteries `t01`..`t13` of
//! `tools/fms-calc-harness/results/` (FileMaker Server 26.0.3.309's engine,
//! generated by `tools/fixpt_battery.py`, calc-values.md 14.9): `Exp`, `Ln`,
//! `Log`, `Lg`, `Sqrt`, `^`, `FV`, `PMT`, `PV`, `NPV`, the trigonometric
//! functions and the arithmetic probes of section 14.2, each at p = 16 to
//! 400 and with `* 10^6` to show every held digit. Every line must be
//! evaluated and match the engine's result text and error code, except the
//! rows where glibc's trigonometric functions round differently from the
//! correctly rounded ones (`GLIBC`).
//!
//! The literal batteries run through the shared literal reader; `t10`
//! (`NPV` over the 12 related records of the FileMaker Server sample) runs
//! through `om_formula::compile` and the evaluator in the sample's copy.

mod samples;
mod support;

use om_calc::eval::Context;
use om_calc::Locale;

/// Lines whose argument reaches the C library as a double whose function
/// value lies within a tiny fraction of a unit of a rounding tie: glibc
/// 2.39, which FileMaker Server calls, returns the other neighbour
/// (calc-values.md 14.8; glibc's results for every battery double are in
/// `results/t11-t12-glibc.txt`).
const GLIBC: &[&str] = &[
    // sin(0x1.17cde069263eap+1) is 1.8e-5 units below a tie: glibc gives
    // .81667302726891533027, the correctly rounded value ...521925.
    "Sin ( 1529 )",
    "SetPrecision ( Sin ( 1529 ) ; 30 )",
];

const LITERAL_BATTERIES: &[&str] = &[
    "t01-exp",
    "t02-ln",
    "t03-log",
    "t04-lg",
    "t05-sqrt",
    "t06-power-int",
    "t07-power-frac",
    "t08-financial",
    "t09-edges",
    "t11-trig",
    "t12-trig-reduce",
    "t13-arith",
];

fn results(name: &str) -> String {
    format!(
        "{}/../../tools/fms-calc-harness/results/{name}",
        env!("CARGO_MANIFEST_DIR")
    )
}

#[test]
fn literal_batteries() {
    let locale = Locale::en_us();
    let mut unexpected = Vec::new();
    let mut seen = vec![false; GLIBC.len()];
    for battery in LITERAL_BATTERIES {
        let (rows, covered, failures) = support::check_harness_results(
            &results(&format!("{battery}.contacts-en.tsv")),
            &locale,
        );
        let mut known = 0;
        for f in &failures {
            match GLIBC.iter().position(|e| f.starts_with(&format!("{e}: "))) {
                Some(i) => {
                    seen[i] = true;
                    known += 1;
                }
                None => unexpected.push(format!("{battery}: {f}")),
            }
        }
        println!(
            "{battery}: {rows} rows, {covered} covered, {} passed, {known} glibc",
            covered - failures.len()
        );
        assert_eq!(covered, rows, "{battery}: every line must be evaluated");
    }
    for f in &unexpected {
        println!("FAIL {f}");
    }
    assert!(unexpected.is_empty(), "{} lines failed", unexpected.len());
    for (e, seen) in GLIBC.iter().zip(seen) {
        assert!(seen, "{e} now passes or is gone: remove it from GLIBC");
    }
}

/// `t10-npv`: the directives `# @ <occurrence> <record>` give the record
/// context, as in `eval_vectors.rs`.
#[test]
fn npv_battery() {
    let text = std::fs::read_to_string(results("t10-npv.fms-sample-en.tsv")).unwrap();
    let mut host = samples::fms_sample();
    let mut context = Context::new();
    let (mut rows, mut failures) = (0, Vec::new());
    for line in text.lines() {
        if let Some(directive) = line.strip_prefix("# @") {
            let words: Vec<&str> = directive.split_whitespace().collect();
            context = Context::new();
            context.occurrence = words.first().and_then(|k| samples::occurrence(k));
            context.record = words.get(1).and_then(|r| r.parse().ok());
            continue;
        }
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let cols: Vec<&str> = line.splitn(4, '\t').collect();
        let [expr, error, _types, expected] = cols[..] else {
            continue;
        };
        rows += 1;
        let source = samples::unescape(expr);
        let outcome = samples::run(&mut host, &source, &context);
        assert!(
            outcome.unsupported.is_empty(),
            "{source}: needs {:?}",
            outcome.unsupported
        );
        if outcome.text != samples::unescape(expected) || outcome.code.to_string() != error {
            failures.push(format!(
                "{source}: got {:?} error {}, want {expected:?} error {error}",
                outcome.text, outcome.code
            ));
        }
    }
    println!("t10-npv: {rows} rows, {} passed", rows - failures.len());
    for f in &failures {
        println!("FAIL {f}");
    }
    assert!(
        rows > 0 && failures.is_empty(),
        "{} lines failed",
        failures.len()
    );
}
